@Timeout(60)
class LmdbCompositeInvocationPlanningTest {

	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();
	private static final IRI OUTER = VF.createIRI("urn:test:composite:Outer");
	private static final IRI CODE = VF.createIRI("urn:test:composite:code");

	@ParameterizedTest
	@CsvSource({ "1,1", "1,2", "3,1", "3,2", "8,2" })
	void disconnectedFiniteCompositeKeepsTheCompleteOuterBag(int outerRows, int duplicateRows,
			@TempDir File directory) {
		LmdbStore store = new LmdbStore(directory, new LmdbStoreConfig("spoc,posc")
				.setFrontierEstimatorMode(FrontierEstimatorMode.AUTHORITATIVE));
		SailRepository repository = new SailRepository(store);
		repository.init();
		try {
			try (var connection = repository.getConnection()) {
				connection.begin();
				for (int ordinal = 0; ordinal < outerRows; ordinal++) {
					connection.add(outer(ordinal), RDF.TYPE, OUTER);
				}
				for (int ordinal = 0; ordinal < 5; ordinal++) {
					connection.add(inner(ordinal), CODE, VF.createLiteral("keep" + ordinal % 2));
				}
				for (int ordinal = 0; ordinal < 3; ordinal++) {
					connection.add(VF.createIRI("urn:test:composite:noise:" + ordinal), CODE, VF.createLiteral("drop"));
				}
				connection.commit();
			}
			assertEquals(FrontierStatisticsAvailability.READY, store.rebuildFrontierStatistics().availability());
			String outerBody = "?outer a <" + OUTER + "> . ";
			String innerBody = "?inner <" + CODE + "> ?kind . FILTER(?kind IN (\"keep0\",\"keep1\")) ";
			NativePlan outerPlan = planAndEvaluate(store, "SELECT ?outer WHERE { " + outerBody + " }");
			NativePlan innerPlan = planAndEvaluate(store, "SELECT ?inner ?kind WHERE { " + innerBody + " }");
			assertEquals(outerRows, outerPlan.bag().values().stream().mapToLong(Long::longValue).sum());
			assertEquals(5L, innerPlan.bag().values().stream().mapToLong(Long::longValue).sum());
			String values = duplicateRows == 1 ? "\"u\"" : "\"u\" \"u\"";
			String query = "SELECT ?outer ?inner ?unused WHERE { " + outerBody
					+ "VALUES ?unused { " + values + " } " + innerBody + " }";
			NativePlan selected = planAndEvaluate(store, query);
			Map<Map<String, Value>, Long> expected = new HashMap<>();
			for (int left = 0; left < outerRows; left++) {
				for (int right = 0; right < 5; right++) {
					expected.put(Map.of("outer", outer(left), "inner", inner(right), "unused", VF.createLiteral("u")),
							(long) duplicateRows);
				}
			}
			assertEquals(expected, selected.bag(), "The same selected tree must preserve every duplicate bag row");
			double composedRows = outerPlan.plan().cost().rows() * innerPlan.plan().cost().rows() * duplicateRows;
			assertTrue(composedRows > 0.0d);
			assertEquals(composedRows, selected.plan().cost().rows(), 0.0d,
					"Independent input estimates must retain their Cartesian unit; isolated child estimates="
							+ outerPlan.plan().cost() + " / " + innerPlan.plan().cost()
							+ ", selected=" + selected.plan().cost() + "\n" + selected.plan().tupleExpr()
							+ "\n" + selected.diagnostics());
		} finally {
			repository.shutDown();
		}
	}

	private static NativePlan planAndEvaluate(LmdbStore store, String sparql) {
		var backing = store.getSailStore();
		try (SailSource source = backing.getExplicitSailSource().fork();
				SailDataset dataset = source.dataset(IsolationLevels.SNAPSHOT_READ)) {
			SailDatasetTripleTermSource tripleSource = new SailDatasetTripleTermSource(backing.getValueFactory(),
					dataset);
			var statistics = backing.getEvaluationStatistics();
			EvaluationStrategy strategy = store.getEvaluationStrategyFactory()
					.createEvaluationStrategy(null, tripleSource, statistics);
			var input = QueryParserUtil.parseTupleQuery(QueryLanguage.SPARQL, sparql, null).getTupleExpr();
			CascadesPlan plan = new LmdbQueryOptimizerPipeline(strategy, tripleSource, statistics)
					.withPreparedQueryEntry(input, null, EmptyBindingSet.getInstance(),
							(prepared, cascades) -> cascades.planPreparedInput(prepared,
									OptimizationGoal.root(prepared, PhysicalProperties.ANY)));
			var step = strategy.precompile(plan.tupleExpr());
			Map<Map<String, Value>, Long> bag = new HashMap<>();
			try (var result = step.evaluate(EmptyBindingSet.getInstance())) {
				while (result.hasNext()) {
					BindingSet row = result.next();
					Map<String, Value> values = new HashMap<>();
					for (var binding : row) {
						values.put(binding.getName(), binding.getValue());
					}
					bag.merge(Map.copyOf(values), 1L, Math::addExact);
				}
			}
			StringBuilder diagnostics = new StringBuilder();
			plan.tupleExpr().visit(new AbstractQueryModelVisitor<RuntimeException>() {
				private int ordinal;

				@Override
				protected void meetNode(QueryModelNode node) {
					if (node instanceof TupleExpr) {
						diagnostics.append("\nnode=")
								.append(ordinal++)
								.append(' ')
								.append(node.getSignature())
								.append("\nplannedStrings=")
								.append(node.getStringMetricsPlanned())
								.append("\nplannedDoubles=")
								.append(node.getDoubleMetricsPlanned())
								.append('\n');
					}
					super.meetNode(node);
				}
			});
			return new NativePlan(plan, Map.copyOf(bag), diagnostics.toString());
		}
	}

	private static IRI outer(int ordinal) {
		return VF.createIRI("urn:test:composite:outer:" + ordinal);
	}

	private static IRI inner(int ordinal) {
		return VF.createIRI("urn:test:composite:inner:" + ordinal);
	}

	private record NativePlan(CascadesPlan plan, Map<Map<String, Value>, Long> bag, String diagnostics) {
	}
}
